-- start the CLI on a file:  duckdb shop.duckdb
CREATE TABLE products (id INTEGER PRIMARY KEY, name VARCHAR, price DECIMAL(8, 2));
INSERT INTO products VALUES (1, 'pen', 1.50), (2, 'book', 12.00);

CREATE TABLE expensive AS                 -- CTAS: save a query's result as a table
    SELECT * FROM products WHERE price > 5;

ATTACH 'archive.duckdb' AS archive;       -- open a second database file
CREATE TABLE archive.products AS SELECT * FROM products;
SELECT count(*) FROM archive.products;    -- 2
DETACH archive;

-- Make a small CSV file to play with
CREATE TABLE s (region VARCHAR, amount INTEGER);
INSERT INTO s VALUES ('north', 10), ('south', 25), ('north', 5);
COPY s TO 'sales.csv' (HEADER);       -- write the table out as a CSV file

-- Query the file directly, as if it were a table
SELECT region, sum(amount) AS total
FROM 'sales.csv'
GROUP BY region ORDER BY total DESC;
-- south | 25
-- north | 15

DESCRIBE SELECT * FROM 'sales.csv';
-- region | VARCHAR
-- amount | BIGINT

-- read Parquet straight from S3, using the keys your Amazon (AWS) tools already have
INSTALL httpfs; LOAD httpfs;
CREATE SECRET aws (TYPE s3, PROVIDER credential_chain);

SELECT count(*) FROM 's3://my-bucket/events/2025/*.parquet';

-- join a live PostgreSQL table with a local file
INSTALL postgres; LOAD postgres;
ATTACH 'dbname=shop host=localhost user=app' AS pg (TYPE postgres, READ_ONLY);

SELECT c.country, sum(e.amount) AS total
FROM 'events.parquet' e
JOIN pg.public.customers c ON c.id = e.customer_id
GROUP BY ALL;
